      { feature: '360° Panoramic Fisheye Lenses', desc: 'Provides full hall coverage without blind spots using a single camera.' },
      { feature: 'Crowd Analytics & Density Alerts', desc: 'Alerts security operators if unusual crowd overcrowding occurs.' },
      { feature: 'Free Smartphone & Tablet Live Access', desc: 'Venue managers can monitor event flow live from anywhere.' }
